<script setup lang="ts">
import { computed } from 'vue'
import MathText from './MathText.vue'

const props = defineProps<{ text?: string }>()

// Only paired **bold** markers are interpreted. Vue escapes all other model
// text; the only HTML inserted downstream is generated by KaTeX with trust off.
const parts = computed(() => {
  const source = String(props.text || '')
  const result: { text: string; strong: boolean }[] = []
  const marker = /\*\*([^*]+)\*\*/g
  let last = 0
  for (const match of source.matchAll(marker)) {
    if (match.index > last) result.push({ text: source.slice(last, match.index), strong: false })
    result.push({ text: match[1], strong: true })
    last = match.index + match[0].length
  }
  if (last < source.length) result.push({ text: source.slice(last), strong: false })
  return result
})
</script>

<template>
  <span class="analysis-rich-text">
    <template v-for="(part, index) in parts" :key="index">
      <strong v-if="part.strong"><MathText :text="part.text" failed-formula-text="公式暂无法显示" /></strong>
      <MathText v-else :text="part.text" failed-formula-text="公式暂无法显示" />
    </template>
  </span>
</template>

<style scoped>
.analysis-rich-text{overflow-wrap:anywhere}
.analysis-rich-text strong{font-weight:600;color:#263950}
.analysis-rich-text :deep(.math-block){display:block;max-width:100%;overflow-x:auto;text-align:center}
.analysis-rich-text :deep(.katex-display){max-width:100%;overflow-x:auto;overflow-y:hidden}
</style>
